// Returns the stored record, or null when this actor has never received one,
// or after ClearMyData has deleted it -- no write either way. Mirrors
// demo_actor.py's GetMyData.
msg.payload = msg.dapr.actor.stateExists ? msg.dapr.actor.state : null;
return [msg, null];

// Stores msg.payload with a server-set timestamp -- mirrors dapr/python-sdk's
// demo_actor.py SetMyData (see this tab's Comment for the source link). The
// request handler commits msg.dapr.actor.nextState only after the reply node
// accepts this proposal; this function never touches storage itself.
function fail(code, message) {
    msg.dapr.actor.error = { code, message };
    return [null, msg];
}

const data = msg.payload;
if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return fail('INVALID_ARGUMENT', 'SetMyData requires a plain JSON object argument');
}

msg.dapr.actor.nextState = { ...data, ts: new Date().toISOString() };
msg.payload = null;
return [msg, null];

// Deletes the actor's entire record -- mirrors demo_actor.py's
// clear_my_data (see this tab's Comment for the source link). This package
// stores one record per actor, so deleting it also clears the
// reminder-trigger function's lastReminder bookkeeping.
// To remove selected fields instead, propose nextState with them omitted.
// For full deletion, nextState must stay absent when deleteState is true.
msg.payload = null;
msg.dapr.actor.deleteState = true;
return [msg, null];

// Increments the persisted counter by 1. dapr/js-sdk's DemoActorCounterImpl
// keeps the counter in memory; this example persists { counter } in the
// actor's own record so it survives a restart.
const current = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
const counter = current + 1;
msg.payload = counter;
msg.dapr.actor.nextState = { counter };
return [msg, null];

// Increments by amount * multiplier (multiplier defaults to 1), mirroring
// DemoActorCounterImpl's countBy. Rejects a non-finite amount or multiplier
// rather than storing NaN/Infinity.
function fail(code, message) {
    msg.dapr.actor.error = { code, message };
    return [null, msg];
}

const arg = msg.payload || {};
const amount = arg.amount;
const multiplier = arg.multiplier === undefined ? 1 : arg.multiplier;
if (typeof amount !== 'number' || !Number.isFinite(amount)) {
    return fail('INVALID_ARGUMENT', 'countBy requires a finite numeric amount');
}
if (typeof multiplier !== 'number' || !Number.isFinite(multiplier)) {
    return fail('INVALID_ARGUMENT', 'countBy requires a finite numeric multiplier');
}

const current = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
const counter = current + amount * multiplier;
msg.payload = counter;
msg.dapr.actor.nextState = { counter };
return [msg, null];

// Returns the persisted counter, 0 when this actor has never been given one
// -- no write either way.
msg.payload = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
return [msg, null];

// Records the most recently fired reminder into DemoActor's own record,
// without disturbing whatever SetMyData already stored -- mirrors
// demo_actor.py's receive_reminder, adapted to this package's single-record
// model. One dapr-actor-method node with Trigger set to Reminder receives
// EVERY reminder of this actor type; the reminder's own name arrives as
// msg.dapr.actor.trigger.name, never inferred from msg.payload. daprd
// retries a failing occurrence up to 3 more times about 1s apart before
// moving on to the next occurrence, so `count` can over-count one logical
// occurrence if an earlier attempt's reply or commit failed after all --
// this flow does not attempt exactly-once counting.
const name = msg.dapr.actor.trigger.name;
const data = msg.payload === undefined ? null : msg.payload;
const state =
    msg.dapr.actor.stateExists &&
    msg.dapr.actor.state &&
    typeof msg.dapr.actor.state === 'object' &&
    !Array.isArray(msg.dapr.actor.state)
        ? msg.dapr.actor.state
        : {};
const previousCount =
    state.lastReminder && state.lastReminder.name === name &&
    Number.isSafeInteger(state.lastReminder.count) && state.lastReminder.count >= 0 &&
    state.lastReminder.count < Number.MAX_SAFE_INTEGER ? state.lastReminder.count : 0;
msg.dapr.actor.nextState = { ...state, lastReminder: { name, data, count: previousCount + 1 } };
msg.payload = null;
return [msg, null];

// Never propose a write from a failure path -- deleteState is also cleared:
// left set, it would make this same message invalid for the fail reply too
// (deleteState is never valid there), turning a caught error into a second,
// uncaught one.
delete msg.dapr.actor.nextState;
delete msg.dapr.actor.deleteState;
msg.dapr.actor.error = { code: 'INTERNAL', message: 'unexpected error' };
return msg;
